def validate(z):
    z=z.copy();z.index=pd.DatetimeIndex(pd.to_datetime(z.index))
    if z.index.tz is not None:z.index=z.index.tz_localize(None)
    z.index=z.index.normalize()
    if not z.index.is_unique or not z.index.is_monotonic_increasing:raise ValueError('Dates must be unique and ascending')
    required=['Open','High','Low','Close','Volume'];z=z[required].astype(float)
    if not np.isfinite(z).all().all():raise ValueError('Missing or nonfinite OHLCV')
    if not z[['Open','High','Low','Close']].gt(0).all().all() or not z.Volume.ge(0).all():raise ValueError('Invalid prices/volume')
    if ((z.High<z[['Open','Close','Low']].max(axis=1)-1e-8)|(z.Low>z[['Open','Close','High']].min(axis=1)+1e-8)).any():raise ValueError('Invalid OHLC range')
    z=z.loc[(z.index>=pd.Timestamp(START))&(z.index<=cutoff)]
    if len(z)<INITIAL_TRAIN+150:raise ValueError(f'Only {len(z)} rows; need at least {INITIAL_TRAIN+150}')
    return z

def adjusted(z,declared=False):
    z=z.copy()
    if 'Adj Close' in z:
        factor=z['Adj Close']/z.Close
        if not (np.isfinite(factor)&(factor>0)).all():raise ValueError('Invalid adjustment factors')
        z[['Open','High','Low','Close']]=z[['Open','High','Low','Close']].mul(factor,axis=0)
    elif not declared:raise ValueError('Adj Close missing; explicitly declare adjusted OHLC for CSV inputs')
    return validate(z)

def load(symbol):
    if DATA_MODE=='demo':
        if symbol!='SPY':raise ValueError('Demo includes only SPY; choose auto or csv for other tickers')
        p=DATA/'SPY_demo.csv';info=json.loads((DATA/'SPY_demo.json').read_text())
        if sha(p)!=info['sha256']:raise ValueError('Demo checksum mismatch')
        z=validate(pd.read_csv(p,index_col=0,parse_dates=True));return z,dict(info,mode='offline demo')
    if DATA_MODE=='csv':
        p=Path(CSV_FILES[symbol]).expanduser();z=adjusted(pd.read_csv(p,index_col=0,parse_dates=True),CSV_ADJUSTED)
        return z,dict(ticker=symbol,source=str(p),sha256=sha(p),mode='csv')
    key=hashlib.sha256(f'{symbol}|{START}|{cutoff.date()}|adjusted-v1'.encode()).hexdigest()[:20]
    p=DATA/(key+'.csv');meta=DATA/(key+'.json')
    if not REFRESH_DATA and p.exists() and meta.exists():
        info=json.loads(meta.read_text())
        if info['ticker']!=symbol or info['start']!=START or info['cutoff']!=str(cutoff.date()) or sha(p)!=info['sha256']:raise ValueError('Cache identity/checksum failure')
        return validate(pd.read_csv(p,index_col=0,parse_dates=True)),dict(info,mode='verified exact cache')
    try:
        import yfinance as yf
        yf.set_tz_cache_location(str(DATA/'yfinance_cache'))
        z=yf.download(symbol,start=START,end=str((cutoff+pd.Timedelta(days=1)).date()),
          auto_adjust=False,actions=False,prepost=False,threads=False,progress=False,timeout=20)
        if z.empty:raise ValueError('Yahoo returned no rows')
        if isinstance(z.columns,pd.MultiIndex):z.columns=z.columns.get_level_values(0)
        z=adjusted(z);z.to_csv(p)
        info=dict(ticker=symbol,source='Yahoo via yfinance',mode='download',sha256=sha(p),
            start=START,cutoff=str(cutoff.date()),retrieved_utc=datetime.now(timezone.utc).isoformat())
        meta.write_text(json.dumps(info,indent=2));return z,info
    except Exception as e:
        if not (p.exists() and meta.exists()):raise RuntimeError(f'Download unavailable and no exact cache: {e}') from e
        info=json.loads(meta.read_text())
        if info['ticker']!=symbol or info['start']!=START or info['cutoff']!=str(cutoff.date()) or sha(p)!=info['sha256']:raise ValueError('Cache identity/checksum failure')
        z=validate(pd.read_csv(p,index_col=0,parse_dates=True));return z,dict(info,mode='verified cache fallback',download_error=str(e))

frames={};provenance={};failures=[]
for symbol in dict.fromkeys([BENCHMARK]+TICKERS):
    try:frames[symbol],provenance[symbol]=load(symbol)
    except Exception as e:
        if symbol==BENCHMARK:raise RuntimeError(f'Benchmark {symbol} unavailable: {e}') from e
        failures.append(dict(ticker=symbol,error=str(e)))
for symbol,z in frames.items():
    provenance[symbol].update(rows=len(z),first=str(z.index[0].date()),last=str(z.index[-1].date()))
    z.to_csv(OUT/(slug(symbol)+'_ohlcv.csv'))
display(pd.DataFrame(provenance).T[['mode','rows','first','last']])
if failures:display(pd.DataFrame(failures))
